def count_calls(fn):
    calls = 0

    def wrapper(*args, **kwargs):
        nonlocal calls
        calls += 1
        result = fn(*args, **kwargs)
        return result, calls

    return wrapper

@count_calls
def add(a, b):
    return a + b

print(add(2, 3))
